"""Supervision Modbus RTU : lecture des registres 0 a 2 du variateur VX-400.

Segment RS-485, 9600 bauds, parite paire, un bit d'arret, esclave 1.
Chaque echange est controle : longueur, adresse, exception, CRC16.
"""

import time

import serial

PORT = "/dev/ttyUSB0"
BAUD = 9600
DELAI = 0.4
ESCLAVE = 1
TENTATIVES = 3
PASSAGES = 10

PLAGES = {
    "vitesse": (0.0, 60.0, 10.0),
    "courant": (0.0, 20.0, 10.0),
    "bus": (300.0, 450.0, 1.0),
}


def crc16(trame):
    crc = 0xFFFF
    for octet in trame:
        crc ^= octet
        for _ in range(8):
            crc = (crc >> 1) ^ 0xA001 if crc & 1 else crc >> 1
    return bytes([crc & 0xFF, crc >> 8])


def requete_lecture(esclave, depart, nombre):
    corps = bytes([
        esclave, 0x03,
        (depart >> 8) & 0xFF, depart & 0xFF,
        (nombre >> 8) & 0xFF, nombre & 0xFF,
    ])
    return corps + crc16(corps)


def lire_registres(port, esclave, depart, nombre):
    requete = requete_lecture(esclave, depart, nombre)
    attendu = 5 + 2 * nombre

    port.reset_input_buffer()
    port.write(requete)
    port.flush()
    reponse = port.read(attendu)

    if len(reponse) != attendu:
        raise TimeoutError(
            "reponse absente ou tronquee (%d/%d octets)" % (len(reponse), attendu)
        )
    if reponse[0] != esclave:
        raise ValueError("adresse esclave inattendue : %02X" % reponse[0])
    if reponse[1] & 0x80:
        raise RuntimeError("exception Modbus %02X" % reponse[2])
    if reponse[-2:] != crc16(reponse[:-2]):
        raise ValueError("controle d'integrite invalide")

    return [
        int.from_bytes(reponse[i:i + 2], "big")
        for i in range(3, 3 + 2 * nombre)
    ]


def interroger_avec_reprises(port, esclave, depart, nombre):
    derniere = None
    for essai in range(TENTATIVES):
        try:
            return lire_registres(port, esclave, depart, nombre), essai + 1
        except (TimeoutError, ValueError, RuntimeError) as erreur:
            derniere = erreur
            time.sleep(0.1 * (essai + 1))
    raise derniere


def valider(nom, valeur):
    bas, haut, echelle = PLAGES[nom]
    brut = valeur / echelle
    if not bas <= brut <= haut:
        raise ValueError("%s hors domaine (%.1f)" % (nom, brut))
    return brut


def main():
    succes = 0
    echecs = 0
    latences = []

    with serial.Serial(
        PORT,
        BAUD,
        parity=serial.PARITY_EVEN,
        stopbits=serial.STOPBITS_ONE,
        timeout=DELAI,
    ) as port:
        for passage in range(1, PASSAGES + 1):
            debut = time.perf_counter()
            try:
                valeurs, essais = interroger_avec_reprises(port, ESCLAVE, 0, 3)
                vitesse = valider("vitesse", valeurs[0])
                courant = valider("courant", valeurs[1])
                bus = valider("bus", valeurs[2])
            except (TimeoutError, ValueError, RuntimeError) as erreur:
                echecs += 1
                print("passage %2d : ECHEC %s" % (passage, erreur))
                continue

            duree = (time.perf_counter() - debut) * 1000.0
            succes += 1
            latences.append(duree)
            print(
                "passage %2d : %5.1f Hz  %4.1f A  %3.0f V  (%.1f ms, essai %d)"
                % (passage, vitesse, courant, bus, duree, essais)
            )

    total = succes + echecs
    print("---")
    print("echanges : %d  reussis : %d  echoues : %d" % (total, succes, echecs))
    if total:
        print("taux de reussite : %.1f %%" % (100.0 * succes / total))
    if latences:
        print("latence moyenne : %.1f ms" % (sum(latences) / len(latences)))
        print("latence maximale : %.1f ms" % max(latences))


if __name__ == "__main__":
    main()
